"use strict";(self.webpackChunkvolby_kscm_cz=self.webpackChunkvolby_kscm_cz||[]).push([[29],{2495:function(e,o,n){n.r(o);var a=n(8453),l=n(6540);function t(e){const o=Object.assign({h1:"h1",p:"p",h2:"h2"},(0,a.R)(),e.components),{BookLink:n}=o;return n||function(e,o){throw new Error("Expected "+(o?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BookLink",!0),l.createElement(l.Fragment,null,l.createElement(o.h1,null,"Komunismus v Česku"),"\n",l.createElement(o.p,null,"V roce 1921 byla založena Komunistická strana Československa. Zločinecká organizace, která má na svědomí tisíce umučených v lágrech a další stovky popravených nebo zabitých při přechodu hranic."),"\n",l.createElement(o.p,null,"Komunistický řežim v Československu věznil přes 205 000 lidí jen proto, že měli jiný názor a nebáli se ho vyslovit. A dalším milionům lidí ovlivnil život odebráním svobody, základních lidských práv. Jak vypadal život za mřížemi, líčí politický vězeň Josef Černý, který v komunistických věznicích strávil téměř patnáct let, v knize ",l.createElement(n,{id:"za-draty-komunismu"}),". Celé období od roku 1945 do pádu režimu shrnuje historik Jan Rychlík v knize ",l.createElement(n,{id:"ceskoslovensko-v-obdobi-socialismu"}),"."),"\n",l.createElement(o.h2,null,"Únorový puč 1948"),"\n",l.createElement(o.p,null,"V únoru 1948 došlo v Československu ke komunistickému převratu. Byla násilně potlačena svobodná pluralita politických stran pod vedením Komunistické strany Československa (KSČ) a usměrňovaná ze Sovětského svazu (SSSR)."),"\n",l.createElement(o.p,null,"Československo tak přešlo od demokracie k totalitě a nastalo období kulturního a ekonomického úpadku. Odpůrci režimu byli vězněni a popravováni. Komunisty byl únorový převrat oficiálně označován za „Vítězství československého pracujícího lidu“."),"\n",l.createElement(o.p,null,"Prvním „dělnickým“ prezidentem se stal předseda KSČ a dosavadní premiér Klement Gottwald."),"\n",l.createElement(o.h2,null,"Milada Horáková"),"\n",l.createElement(o.p,null,"Komunisty vykonstruovaný politický monstr proces na jehož konci stály čtyři rozsudky smrti. Kromě české političky a právničky Milady Horákové šlo o Jana Buchala, Záviše Kalandru a Oldřicha Pecla."),"\n",l.createElement(o.p,null,"Trest smrti na nich byl vykonán i přesto, že četné osobnosti světové politiky, vědy i kultury (mimo jiné Albert Einstein, britský premiér Winston Churchill i vdova po zesnulém americkém prezidentovi Eleanor Rooseweltová) žádali prezidenta Klementa Gottwalda o milost pro odsouzené. Její příběh od dětství až po popravu vypráví komiksová kniha ",l.createElement(n,{id:"milada-horakova"}),"."),"\n",l.createElement(o.h2,null,"Likvidace sedláků v 50. letech"),"\n",l.createElement(o.p,null,"Provedení kolektivizace dostal Klement Gottwald od Sovětů za úkol již v červnu 1948. Trvala přes deset let a měla katastrofální dopad na životy tisíců rodin, úroveň zemědělství, krajinu a vztahy mezi lidmi na venkově."),"\n",l.createElement(o.p,null,"V dubnu 1949 zahájili komunisté masivní kampaň vyzývající zemědělce k zakládání JZD. Ta se však nesetkala s takovým ohlasem, jaký si představovali, a tak začali být zemědělci ke vstupu do družstev nuceni násilnými metodami."),"\n",l.createElement(o.p,null,'V listopadu 1951 spustili akci "Kulak", během níž byly vystěhovávány rodiny vzpurných sedláků z vesnic. Součástí represe bylo také posílání „kulaků“ do pracovních táborů a Pomocných technických praporů (PTP).'),"\n",l.createElement(o.h2,null,"Likvidace klášterů v roce 1950"),"\n",l.createElement(o.p,null,"Dva roky po únorovém převratu došlo ke komunistickou mocí zosnované násilné akci znamenající na další čtyři desetiletí faktickou likvidaci mužských klášterů."),"\n",l.createElement(o.p,null,'Pro přepadení klášterů, protizákonnou deportaci a internaci řeholníků a zabavení majetku řádů a kongregací bylo použito označení "akce K", neboli akce "Kláštery".'),"\n",l.createElement(o.h2,null,"Likvidace pilotů RAF"),"\n",l.createElement(o.p,null,"Po návratu do vlasti se bývalí příslušníci britského letectva těšili velké popularitě. Jejich sláva ale netrvala dlouho. Po únorovém puči v únoru 1948 komunisté veterány RAF označovali za zrádce nebo špiony."),"\n",l.createElement(o.p,null,"Nové poměry, které jim navzdory účasti v odboji přinesly ponížení a existenční nejistotu, přinutily mnohé z nich k emigraci. Další dlouhé roky strávili ve vězení nebo v pracovních táborech."),"\n",l.createElement(o.h2,null,"Invaze vojsk v roce 1968"),"\n",l.createElement(o.p,null,"Přesně podle připraveného plánu začaly jednotky vojsk Varšavské smlouvy (SSSR, NDR, Polska, Maďarska a Bulharska) před půlnocí 20. srpna 1968 obsazovat ČSSR. Tanky a obrněné transportéry s bílými invazními pruhy silou ukončily tzv. pražské jaro."),"\n",l.createElement(o.p,null,"V ranních hodinách obsadili okupanti budovy důležitých úřadů a redakce sdělovacích prostředků. S okupací nesouhlasila nejen veřejnost, ale také vláda a další politici."),"\n",l.createElement(o.p,null,'Při následných jednáních předali kolaboranti z řad KSČ sovětské straně tzv. "zvací dopis", kterým se zpětně snažili legalizovat vpád okupačních vojsk. Dopis podepsali členové ÚV KSČ Vasil Biľak, Alois Indra, Antonín Kapek, Drahomír Kolder a Oldřich Švestka. Rok nadějí i zklamání zachycuje z dobových novin a rozhovorů s pamětníky kniha ',l.createElement(n,{id:"bajecny-a-horky-rok-1968"}),"."),"\n",l.createElement(o.h2,null,"Jan Palach"),"\n",l.createElement(o.p,null,"Na protest proti sovětské okupaci a pokračujícím ústupkům okupantům ze strany čs. politické reprezentace se 16.1.1969 upálil v horní části pražského Václavského náměstí."),"\n",l.createElement(o.p,null,"Jeho pohřeb 25.1.1969 v Praze se stal celonárodní manifestací proti sovětské okupaci. V Palachových stopách šli další mladí lidé např. Josef Hlavatý, Miroslav Malinka, Blanka Nacházelová, Evžen Plocek a Jan Zajíc. Palachův život i dobu, ve které vyrůstal, ukazuje v dobových fotografiích kniha ",l.createElement(n,{id:"jan-palach"}),"."),"\n",l.createElement(o.h2,null,"Železná opona"),"\n",l.createElement(o.p,null,"Bylo příznačné označení obludného systému ostnatých drátů, betonových stěn, minových polí, stěn vysokého napětí, strážních stanovišť a samostřílů, jehož hlavním cílem bylo za jakoukoli cenu zabránit občanům v útěku na Západ."),"\n",l.createElement(o.p,null,"Na hranicích Československa zahynulo v období komunistického režimu mezi lety 1948 a 1989 nejméně 266 lidí."),"\n",l.createElement(o.h2,null,"Období normalizace"),"\n",l.createElement(o.p,null,"Navzdory očekávání některých politiků, okupační vojska SSSR z Československa po zásahu neodešla a nejrůznějším způsobem se vměšovala do vnitřních záležitostí Československé republiky."),"\n",l.createElement(o.p,null,"Nastalo období zmrazení demokratizačního procesu v Československu a postupné likvidace většiny jeho výsledků, systémovou obnovu neostalinismu, postupné unavování a otupování politického odporu."),"\n",l.createElement(o.p,null,"Současně to bylo období neutěšeného ekonomického vývoje, devastace životního prostředí, úpadku pracovní morálky, resp. morálky vůbec. Režim pracoval pomocí hrozeb, tlaků, soustavného zpochybňování a očerňování jinak smýšlejících lidí, manipulací s fakty i hodnotami, individuální i sociální korupcí. Jak normalizaci prožívali pamětníci a co z ní přešlo do dnešní společnosti, zkoumá Daniel Kunštát v knize ",l.createElement(n,{id:"ceska-zkusenost-s-komunismem"}),"."),"\n",l.createElement(o.h2,null,"Charta 77"),"\n",l.createElement(o.p,null,"Charta 77 vznikla na protest proti nedodržování základních lidských práv a svobod v totalitním Československu. Všeobecná nevole vůči tehdy již téměř třicetileté totalitní vládě komunistů byla shrnuta v prohlášení, jež bezprostředně reflektovalo neplnění dohody o dodržování základních lidských práv a svobod."),"\n",l.createElement(o.p,null,"Jak se dalo čekat, signatáři a podporovatelé Charty se stali terčem brutální represe. Čelili vyhazovům z práce a škol, zastrašování, špiclování, domovním prohlídkám, zavírání do vězení. Za týden po zveřejnění textu putovali do vězení Václav Havel a novinář Jiří Lederer. Dějinám disentu a jeho podílu na pádu komunistických režimů se věnuje sborník historiků ",l.createElement(n,{id:"charta-77"},"Charta 77: Od obhajoby lidských práv k demokratické revoluci"),"."),"\n",l.createElement(o.h2,null,"Sametová revoluce 1989"),"\n",l.createElement(o.p,null,"17. listopadu 1989 se konala povolená demonstrace k padesátému výročí uzavření českých vysokých škol. Po jejím oficiálním ukončení se velká část demonstrantů vydala na pochod do centra města, aby projevila nesouhlas s tehdejším komunistickým režimem."),"\n",l.createElement(o.p,null,"Policie demonstranty postupně obklíčila na Národní třídě a surově je zbila, což odstartovalo tzv. sametovou revoluci, která vedla k pádu komunistického režimu."))}o.default=function(e){void 0===e&&(e={});const{wrapper:o}=Object.assign({},(0,a.R)(),e.components);return o?l.createElement(o,e,l.createElement(t,e)):t(e)}}}]);
